        'package_bytes'=>$packageBytes,'application_max_allowed_packet'=>$packetLimit,'producer_preflights'=>4,
        'accepted_facts_sha256'=>$oldFactsSha,'accepted_facts_count'=>$oldFactsCount,'operator_provider_calls'=>0]));
    $authorizedOld=static function()use($app,$work,$intentSha,$resolvedSha):bool{
        hotelInstalled($app);hotelRead($work.'/intent.json',65536,null,$intentSha);hotelRead($work.'/resolved-boundary.json',65536,null,$resolvedSha);hotelRuntime($app,HOTEL_OLD_RUNTIME,HOTEL_PREDECESSOR,HOTEL_OLD_BOOTSTRAP);return true;
