        'public_payload_sha256'=>HOTEL_PAYLOAD_SHA,'inputs_sha256'=>$package['inputs_sha256'],'retained_admission'=>$package['retained_admission'],
        'expected_stages'=>4,'expected_scopes'=>16,'maximum_calls'=>8,'accepted_facts_sha256'=>$oldFactsSha,'accepted_facts_count'=>$oldFactsCount,
