    hotelWriteNew($work.'/preflight.sealed.json',$preflightSealBytes);$report['preflight_sealed_sha256']=hash('sha256',$preflightSealBytes);
    $report['phase']='bootstrap_next';hotelWriteNew($work.'/bootstrap-next.intent.json',HotelServerInputs::json(['operation_id'=>HOTEL_OPERATION,'github_run_id'=>$run,
        'resolved_boundary_sha256'=>$resolvedSha,'intent_sha256'=>$intentSha,'state'=>'single_invocation_starting']));
    $report['bootstrap_next_invoked']=true;$disabled=$cycle->bootstrapNext(HOTEL_PREDECESSOR,HOTEL_OLD_BOOTSTRAP,HOTEL_OLD_BASELINE,HOTEL_CAMPAIGN,$inputs,$plan,$authorizedOld);
