    foreach($before as $key=>$value)if($key!=='enabled'&&$after[$key]!==$value)hotelFail('predecessor_boundary_changed');
    $seedProof=hotelSeed($pdo,$disabled,$package,$plan,$carried,$predecessorReceipts);$report['predecessor_receipt_refs_core_verified']=true;$seedSha=$seedProof['seed_sha256'];$bootstrapPin=$seedProof['bootstrap_sha256'];
