    hotelWriteNew($staged,$runtimeBytes);hotelWriteNew($work.'/runtime-switch.intent.json',HotelServerInputs::json(['expected_old_sha256'=>HOTEL_OLD_RUNTIME,'new_sha256'=>$runtimeSha,'bootstrap_sha256'=>$bootstrapPin,'enabled_campaigns'=>0]));
    $report['phase']='runtime_switch';hotelInstalled($app);hotelEnabled($pdo,null);
    hotelRuntime($app,HOTEL_OLD_RUNTIME,HOTEL_PREDECESSOR,HOTEL_OLD_BOOTSTRAP);hotelRead($work.'/runtime.before.json',65536,strlen($oldRuntimeBytes),HOTEL_OLD_RUNTIME);
    $report['runtime_switch_started']=true;if(!rename($staged,$runtimePath))hotelFail('runtime_switch_unconfirmed');
    hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);$report['runtime_file_installed']=true;$report['runtime_sha256']=$runtimeSha;
    hotelWriteNew($work.'/runtime-switch.readback.json',HotelServerInputs::json(['runtime_sha256'=>$runtimeSha,'campaign_id'=>HOTEL_CAMPAIGN,'bootstrap_sha256'=>$bootstrapPin,'enabled_campaigns'=>0]));
    $authorizedNew=static function()use($app,$work,$intentSha,$resolvedSha,$runtimeSha,$bootstrapPin):bool{
        hotelInstalled($app);hotelRead($work.'/intent.json',65536,null,$intentSha);hotelRead($work.'/resolved-boundary.json',65536,null,$resolvedSha);hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);return true;
    };
