    hotelInstalled($app);hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);hotelEnabled($pdo,HOTEL_CAMPAIGN);
    $report['enabled_snapshot']=$enabled;$report['activated_at_utc']=gmdate('c');$report['continuation']='existing_cron_only';$report['central41']='UNKNOWN';
