    $observation=hotelObserveStartup($pdo,$plan,$policy,$package['inputs_sha256'],$seedSha,$bootstrapPin,$package['pins']['criteria'],$principals,$package['retained_admission']);
    $report['startup_observation']=$observation;$report['first_provider_call_confirmed']=$observation['provider_calls_confirmed']>0;
    $report['first_new_acceptance_confirmed']=$observation['first_new_acceptance_confirmed'];
